      perfil:{
        profTotalSondagem: $('#f-profTotalSondagem').value, diametroSondagem: $('#f-diametroSondagem').value,
        naSondagem: $('#f-naSondagem').value, profTotalPoco: $('#f-profTotalPoco').value,
        diametroPoco: $('#f-diametroPoco').value, naEstabilizado: $('#f-naEstabilizado').value,
        tuboFiltro: $('#f-tuboFiltro').value, tuboLiso: $('#f-tuboLiso').value,
        preFiltro: $('#f-preFiltro').value, seloConcreto: $('#f-seloConcreto').value,
        seloBentonitaCima: $('#f-seloBentonitaCima').value, seloBentonitaBaixo: $('#f-seloBentonitaBaixo').value,
        preenchimentoFuro: getRadio('preenchimentoFuro'), furoOutrosTxt: $('#f-furoOutrosTxt').value,
        produtoSolo: getRadio('produtoSolo'), produtoProf: $('#f-produtoProf').value
      },
      carimbo:{
        empresa: $('#f-empresa').value, cliente: $('#f-cliente').value, escala: $('#f-escala').value,
        desenhadoPor: $('#f-desenhadoPor').value, verificadoPor: $('#f-verificadoPor').value
      },
      // Coordenadas do local e caminho da foto no Supabase Storage (o arquivo em
      // si não fica aqui, só a referência — ver uploadFotoLocal()/loadFotoPreview()).
      local:{
        latitude: $('#f-latitude').value, longitude: $('#f-longitude').value,
        fotoPath: window.__fotoPath || null
      },
