  function renderForm(d){
    d = d || {};
    var meta=d.meta||{}, equip=d.equip||{}, perfil=d.perfil||{}, carimbo=d.carimbo||{};
    $('#f-obra').value=meta.obra||''; $('#f-nOS').value=meta.nOS||''; $('#f-tecnico').value=meta.tecnico||'';
    $('#f-equipeSondagem').value=meta.equipeSondagem||''; $('#f-tempo').value=meta.tempo||'';
    $('#f-sondagemNo').value=meta.sondagemNo||''; $('#f-pocoNo').value=meta.pocoNo||''; $('#f-localizacao').value=meta.localizacao||'';
    $('#f-dataInicio').value=meta.dataInicio||''; $('#f-horaInicio').value=meta.horaInicio||'';
    $('#f-dataTermino').value=meta.dataTermino||''; $('#f-horaTermino').value=meta.horaTermino||'';

    setRadio('leituraNA', equip.leituraNA||''); $('#f-naOutroTxt').value=equip.naOutroTxt||'';
    setRadio('medicaoVOC', equip.medicaoVOC||''); $('#f-vocOutroTxt').value=equip.vocOutroTxt||'';
    $('#f-nEquipamento').value=equip.nEquipamento||'';
    setRadio('sondagemTipo', equip.sondagemTipo||''); $('#f-tipoOutroTxt').value=equip.tipoOutroTxt||'';

    setLitRows(d.litologia||[]);
    setVocRows(d.voc||[]);

    $('#f-profTotalSondagem').value=perfil.profTotalSondagem||''; $('#f-diametroSondagem').value=perfil.diametroSondagem||'';
    $('#f-naSondagem').value=perfil.naSondagem||''; $('#f-profTotalPoco').value=perfil.profTotalPoco||'';
    $('#f-diametroPoco').value=perfil.diametroPoco||''; $('#f-naEstabilizado').value=perfil.naEstabilizado||'';
    $('#f-tuboFiltro').value=perfil.tuboFiltro||''; $('#f-tuboLiso').value=perfil.tuboLiso||'';
    $('#f-preFiltro').value=perfil.preFiltro||''; $('#f-seloConcreto').value=perfil.seloConcreto||'';
    $('#f-seloBentonitaCima').value=perfil.seloBentonitaCima||''; $('#f-seloBentonitaBaixo').value=perfil.seloBentonitaBaixo||'';
    setRadio('preenchimentoFuro', perfil.preenchimentoFuro||''); $('#f-furoOutrosTxt').value=perfil.furoOutrosTxt||'';
    setRadio('produtoSolo', perfil.produtoSolo||''); $('#f-produtoProf').value=perfil.produtoProf||'';

    $('#f-empresa').value=carimbo.empresa||''; $('#f-cliente').value=carimbo.cliente||'';
    $('#f-escala').value=carimbo.escala||''; $('#f-desenhadoPor').value=carimbo.desenhadoPor||'';
    $('#f-verificadoPor').value=carimbo.verificadoPor||'';

    var local = d.local||{};
    $('#f-latitude').value = local.latitude||''; $('#f-longitude').value = local.longitude||'';
    updateGeoMapLink();
    setGeoStatus('');
    renderFotoPreview(local.fotoPath||null);

    window.__isExample = !!d.isExample;
    $('#example-badge').style.display = window.__isExample ? '' : 'none';
    updateTopbar();
    redrawLith();
  }

  function updateTopbar(){
    $('#tb-sondagem').textContent = $('#f-sondagemNo').value || 'nova sondagem';
    $('#tb-obra').textContent = $('#f-obra').value || 'Sem nome da obra';
  }

  function markDirty(){
    if(window.__isExample){
      window.__isExample = false;
      $('#example-badge').style.display = 'none';
    }
    updateTopbar();
  }

